def largestSuffixStart(s):
    n = len(s)
    i, j, k = 0, 1, 0
    while j + k < n:
        a, b = s[i + k], s[j + k]
        if a == b:
            k += 1
            continue
        if a < b:
            i += k + 1
            if i >= j:
                j = i + 1
        else:
            j += k + 1
        k = 0
    return i
